const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Kabul location and 30-mile radius (~48.28 km)
  const kabulCoords = [69.18, 34.52]; // [lon, lat]
  const radiusKm = 48.28; // 30 miles
  const kabulPoint = ee.Geometry.Point(kabulCoords);
  const kabulBuffer = kabulPoint.buffer(radiusKm * 1000); // Convert to meters

  // 2. Fetch MODIS Snow Water Equivalent data
  const feb2017 = ee.ImageCollection('MODIS/061/MOD10A1')
    .filterDate('2017-02-01', '2017-02-28')
    .filterBounds(kabulBuffer)
    .select('SWE');

  const feb2018 = ee.ImageCollection('MODIS/061/MOD10A1')
    .filterDate('2018-02-01', '2018-02-28')
    .filterBounds(kabulBuffer)
    .select('SWE');

  // 3. Check collection sizes
  const size2017 = feb2017.size().getInfo();
  const size2018 = feb2018.size().getInfo();

  console.log(`Feb 2017 Images: ${size2017}`);
  console.log(`Feb 2018 Images: ${size2018}`);

  if (size2017 === 0 || size2018 === 0) {
    console.log('C1');
    return;
  }

  // 4. Merge and compute mean SWE for each month
  const mean2017 = feb2017.mean();
  const mean2018 = feb2018.mean();

  // 5. Calculate mean SWE values within the buffer region
  const stats2017 = mean2017.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: kabulBuffer,
    scale: 500,
    maxPixels: 1e9
  });

  const stats2018 = mean2018.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: kabulBuffer,
    scale: 500,
    maxPixels: 1e9
  });

  // 6. Extract SWE values
  const swe2017 = stats2017.get('SWE').getInfo();
  const swe2018 = stats2018.get('SWE').getInfo();

  console.log(`Feb 2017 Mean SWE: ${swe2017}`);
  console.log(`Feb 2018 Mean SWE: ${swe2018}`);

  // 7. Validate results
  if (swe2017 === null || swe2018 === null || isNaN(swe2017) || isNaN(swe2018)) {
    console.log('C3');
    return;
  }

  // 8. Pixel count check
  const count2017 = mean2017.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: kabulBuffer,
    scale: 500,
    maxPixels: 1e9
  }).get('SWE').getInfo();

  const count2018 = mean2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: kabulBuffer,
    scale: 500,
    maxPixels: 1e9
  }).get('SWE').getInfo();

  console.log(`Feb 2017 Valid Pixels: ${count2017}`);
  console.log(`Feb 2018 Valid Pixels: ${count2018}`);

  if (count2017 === 0 || count2018 === 0) {
    console.log('C2');
    return;
  }

  // 9. Compare and output answer
  console.log(`Comparison: 2017=${swe2017.toFixed(2)} mm, 2018=${swe2018.toFixed(2)} mm`);

  if (swe2018 > swe2017) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
